.cpu-load-chart {
    position: relative;
    width: 100%;
    min-width: 0;
}

/*
 * Yagr раскрашивает подложку, сетку и оси через собственные CSS-переменные.
 * Привязываем их к семантическим токенам uikit — тогда график следует
 * текущей теме (light / dark / *-hc) без ручных переопределений под тёмную тему.
 */
.cpu-load-chart .yagr {
    --yagr-background: var(--g-color-base-background);
    --yagr-grid: var(--g-color-line-generic);
    --yagr-axis-stroke: var(--g-color-infographics-axis);
    --yagr-font-family: var(--g-text-body-font-family);
    --yagr-tooltip-font-family: var(--g-text-body-font-family);
}

.cpu-load-chart__canvas {
    width: 100%;
    height: 100%;
}

